const fs=require('fs'), path=require('path');
const test='src/transport/ws/messageHandler.test.ts';
const lines=fs.readFileSync(test,'utf8').split('\\n');
const map=new Map();
for(let i=0;i<lines.length;i++){const m=lines[i].match(/\\bit\\((?:'(["'^'"']+)'|\"(["'^"]+)")/);if(m)map.set(m[1]||m[2],i+1)}
const files=[];
for(const root of ['"'specs','adrs']) if(fs.existsSync(root)) for(const d of fs.readdirSync(root,{recursive:true})) if(d.endsWith('.md')) files.push(path.join(root,d));
let out='*** Begin Patch\\n';
for(const file of files){
 const old=fs.readFileSync(file,'utf8');
 const neu=old.replace(/\\(\\[validated by: (["'^'"\\]]+)\\]\\(\\.\\.\\/\\.\\.\\/src\\/transport\\/ws\\/messageHandler\\.test\\.ts#L\\d+\\)\\)/g,(whole,title)=>{
   const n=map.get(title); return n?whole.replace(/#L\\d+/, '#L'+n):whole;
 });
 if(neu"'!==old){
  out+=`*** Update File: ${path.resolve(file)}'"\\n"'`;
  const a=old.split('"'\\n'),b=neu.split('\\n');
  for(let i=0;i<a.length;i++) if(a[i]"'!==b[i]) out+=`@@'"\\n-"'${a[i]}'"\\n+"'${b[i]}'"\\n"'`;
 }
}
out+='"'*** End Patch\\n';
process.stdout.write(out);
